// EffMeet2 高保真原型生成器 v2
// 视觉系统：浅暖灰底 + 白色大圆角卡片 + 柔和阴影 + 珊瑚橙品牌色
// 屏1 会中（含底部弹层候选卡 + 真实草图） / 屏2 会后观点地图

const FONT = "Inter";
const BG = "#F6F7F9";
const CARD = "#FFFFFF";
const INK = "#1A1D21";
const GRAY = "#6B7280";
const FAINT = "#9CA3AF";
const LINE = "#ECEEF1";
const BRAND = "#FF6B4A";       // 珊瑚橙
const BRAND_D = "#F0522E";     // 深珊瑚
const GREEN_BG = "#DCFCE7", GREEN_TX = "#16A34A", GREEN_SOFT = "#F0FDF4";
const ORANGE_BG = "#FEF3C7", ORANGE_TX = "#D97706";
const AV_ORANGE = "#FF6B4A", AV_INDIGO = "#6366F1", AV_CYAN = "#0EA5E9";

function rgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}
function solid(hex) { return [{ type: "SOLID", color: rgb(hex) }]; }
function rgba(hex, a) { const c = rgb(hex); c.a = a; return [{ type: "SOLID", color: c }]; }
function softShadow() {
  return [{ type: "DROP_SHADOW", color: { r: 0.1, g: 0.11, b: 0.13, a: 0.07 }, offset: { x: 0, y: 6 }, radius: 16, spread: 0, visible: true, blendMode: "NORMAL" }];
}
function brandGradient() {
  return [{
    type: "GRADIENT_LINEAR",
    gradientTransform: [[0, 1, 0], [-1, 0, 1]],
    gradientStops: [
      { color: { r: 1, g: 0.52, b: 0.38, a: 1 }, position: 0 },
      { color: { r: 0.94, g: 0.32, b: 0.18, a: 1 }, position: 1 }
    ]
  }];
}

// base64 → bytes（Figma 沙箱无 Buffer）
function b64ToBytes(b64) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const lookup = new Uint8Array(256);
  for (let i = 0; i < 64; i++) lookup[chars.charCodeAt(i)] = i;
  let padding = 0;
  if (b64.endsWith("==")) padding = 2; else if (b64.endsWith("=")) padding = 1;
  const len = Math.floor(b64.length / 4) * 3 - padding;
  const bytes = new Uint8Array(len);
  let p = 0;
  for (let i = 0; i < b64.length; i += 4) {
    const n = (lookup[b64.charCodeAt(i)] << 18) | (lookup[b64.charCodeAt(i + 1)] << 12) | ((lookup[b64.charCodeAt(i + 2)] || 0) << 6) | (lookup[b64.charCodeAt(i + 3)] || 0);
    if (p < len) bytes[p++] = (n >> 16) & 255;
    if (p < len) bytes[p++] = (n >> 8) & 255;
    if (p < len) bytes[p++] = n & 255;
  }
  return bytes;
}

function F(parent, name, o = {}) {
  const f = figma.createFrame();
  f.name = name;
  if (o.layout) f.layoutMode = o.layout;
  if (o.gap != null) f.itemSpacing = o.gap;
  const pad = o.pad ?? 0;
  f.paddingLeft = f.paddingRight = f.paddingTop = f.paddingBottom = pad;
  if (o.padX != null) f.paddingLeft = f.paddingRight = o.padX;
  if (o.padY != null) f.paddingTop = f.paddingBottom = o.padY;
  if (o.primary) f.primaryAxisAlignItems = o.primary;
  if (o.counter) f.counterAxisAlignItems = o.counter;
  if (o.gradient === "brand") f.fills = brandGradient();
  else if (o.fill) f.fills = solid(o.fill);
  else f.fills = [];
  if (o.fillA) f.fills = rgba(o.fillA[0], o.fillA[1]);
  if (o.stroke) { f.strokes = solid(o.stroke); f.strokeWeight = o.strokeWeight ?? 1; f.strokeAlign = "INSIDE"; }
  if (o.radius != null) f.cornerRadius = o.radius;
  if (o.topRadius != null) { f.topLeftRadius = o.topRadius; f.topRightRadius = o.topRadius; }
  if (o.clip) f.clipsContent = true;
  parent.appendChild(f);
  const rw = typeof o.w === "number" ? o.w : null;
  const rh = typeof o.h === "number" ? o.h : null;
  if (rw != null || rh != null) f.resize(rw ?? f.width, rh ?? f.height);
  // fill 要按父级布局方向选择轴向：VERTICAL 父级里横向是交叉轴（STRETCH），HORIZONTAL 父级里横向是主轴（layoutGrow）
  const pVert = parent.layoutMode === "VERTICAL";
  if (o.w === "fill") { if (pVert) f.layoutAlign = "STRETCH"; else f.layoutGrow = 1; }
  if (o.h === "fill") { if (pVert) f.layoutGrow = 1; else f.layoutAlign = "STRETCH"; }
  if (o.shadow) f.effects = softShadow();
  if (o.abs) { f.layoutPositioning = "ABSOLUTE"; if (o.x != null) f.x = o.x; if (o.y != null) f.y = o.y; }
  return f;
}

function T(parent, name, chars, o = {}) {
  const t = figma.createText();
  t.name = name;
  t.fontName = { family: FONT, style: o.style || "Regular" };
  t.characters = chars;
  t.fontSize = o.size ?? 14;
  t.fills = solid(o.color || INK);
  parent.appendChild(t);
  if (o.fillWidth) { t.layoutAlign = "STRETCH"; t.textAutoResize = "HEIGHT"; }
  if (o.align) t.textAlignHorizontal = o.align;
  if (o.ls != null) t.letterSpacing = { unit: "PIXELS", value: o.ls };
  return t;
}

function pill(parent, label, bg, fg, bold) {
  const c = F(parent, "pill·" + label, { layout: "HORIZONTAL", padX: 10, padY: 5, fill: bg, radius: 999 });
  T(c, "label", label, { size: 11, style: bold ? "Bold" : "Medium", color: fg });
  return c;
}

function avatar(parent, ch, color, size) {
  const a = F(parent, "头像·" + ch, { layout: "HORIZONTAL", w: size, h: size, primary: "CENTER", counter: "CENTER", fill: color, radius: size / 2 });
  T(a, "字", ch, { size: size * 0.44, style: "Bold", color: "#FFFFFF" });
  return a;
}

const MIC_SVG = `<svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" viewBox="0 0 24 24" fill="none"><rect x="9" y="2" width="6" height="12" rx="3" fill="#FFFFFF"/><path d="M5 10a7 7 0 0 0 14 0" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round"/><path d="M12 19v3" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round"/></svg>`;

const SKETCH_B64 = "";

async function main() {
  await figma.loadFontAsync({ family: FONT, style: "Regular" });
  await figma.loadFontAsync({ family: FONT, style: "Medium" });
  await figma.loadFontAsync({ family: FONT, style: "Bold" });

  const sketchImg = figma.createImage(b64ToBytes(SKETCH_B64));

  // ================= 屏 1 · 会中 =================
  const s1 = F(figma.currentPage, "屏1 会中-远程成员", { layout: "VERTICAL", w: 390, h: 844, fill: BG, radius: 40, clip: true, x: 0, y: 0 });

  // 顶部品牌区
  const hero = F(s1, "顶部品牌区", { layout: "VERTICAL", w: 390, gradient: "brand", padX: 20, padY: 0, abs: true, x: 0, y: 0 });
  hero.resize(390, 196);
  const sb = F(hero, "状态栏", { layout: "HORIZONTAL", w: "fill", h: 54, primary: "SPACE_BETWEEN", counter: "CENTER", padY: 8 });
  T(sb, "时间", "9:41", { size: 15, style: "Bold", color: "#FFFFFF" });
  T(sb, "网络", "5G", { size: 12, style: "Medium", color: "#FFFFFF" });
  const heroMid = F(hero, "会议信息", { layout: "VERTICAL", w: "fill", gap: 8, padY: 6 });
  T(heroMid, "会议名", "回收箱方案评审", { size: 21, style: "Bold", color: "#FFFFFF" });
  const heroRow = F(heroMid, "状态与成员", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER" });
  const recPill = F(heroRow, "录音状态", { layout: "HORIZONTAL", gap: 6, counter: "CENTER", padX: 10, padY: 5, fillA: ["#FFFFFF", 0.22], radius: 999 });
  const dot = figma.createEllipse(); dot.name = "红点"; dot.resize(7, 7); dot.fills = solid("#FFFFFF");
  recPill.appendChild(dot);
  T(recPill, "文字", "录音中 · 3 人在线", { size: 11, style: "Medium", color: "#FFFFFF" });
  const avs = F(heroRow, "成员头像", { layout: "HORIZONTAL", gap: -8 });
  avatar(avs, "甲", AV_INDIGO, 28);
  avatar(avs, "乙", AV_CYAN, 28);
  avatar(avs, "丙", "#FFFFFF", 28);

  // 内容区（灰底，向上叠入头部）
  const ct = F(s1, "内容区", { layout: "VERTICAL", w: 390, gap: 14, padX: 16, padY: 16, abs: true, x: 0, y: 168 });
  ct.resize(390, 560);

  // 转写卡
  const lv = F(ct, "现场转写卡", { layout: "HORIZONTAL", w: "fill", gap: 10, counter: "CENTER", padX: 14, padY: 12, fill: CARD, radius: 16, shadow: true });
  F(lv, "橙色竖条", { w: 3, h: 26, fill: BRAND, radius: 2 });
  const lvTx = F(lv, "转写文字", { layout: "HORIZONTAL", w: "fill", gap: 4, counter: "CENTER" });
  T(lvTx, "来源", "现场 · 甲：", { size: 12, style: "Bold" });
  T(lvTx, "内容", "折叠的结构强度够不够？回收箱会被撞…", { size: 12, color: GRAY, fillWidth: true });

  // 现场画面卡
  const pic = F(ct, "现场画面卡", { layout: "VERTICAL", w: "fill", gap: 10, pad: 12, fill: CARD, radius: 20, shadow: true });
  const picImg = F(pic, "草图", { w: "fill", h: 168, radius: 14, clip: true, fill: "#F3F4F6" });
  picImg.fills = [{ type: "IMAGE", imageHash: sketchImg.hash, scaleMode: "FILL" }];
  const picRow = F(pic, "AI描述行", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER", padX: 2 });
  const picL = F(picRow, "描述文字", { layout: "VERTICAL", gap: 2 });
  picL.layoutGrow = 1;
  T(picL, "标签", "AI 描述", { size: 10, style: "Medium", color: FAINT, ls: 0.5 });
  T(picL, "内容", "三格回收箱正面，顶部投放口，右上「满溢检测？」", { size: 12, color: GRAY });
  T(picRow, "查看原图", "查看原图 ›", { size: 12, style: "Medium", color: BRAND });

  // 我的观点
  const secT = F(ct, "观点标题行", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER", padX: 2 });
  T(secT, "标题", "我的观点", { size: 16, style: "Bold" });
  pill(secT, "2 条", "#FFE9E3", BRAND_D, true);

  const op1 = F(ct, "观点卡1", { layout: "VERTICAL", w: "fill", gap: 8, pad: 14, fill: CARD, radius: 20, shadow: true });
  const op1R = F(op1, "元信息行", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER" });
  const op1L = F(op1R, "左组", { layout: "HORIZONTAL", gap: 8, counter: "CENTER" });
  avatar(op1L, "我", AV_ORANGE, 26);
  T(op1L, "时间", "2 分钟前", { size: 11, color: FAINT });
  pill(op1R, "可能未被回应", ORANGE_BG, ORANGE_TX);
  T(op1, "观点内容", "满溢检测用重量传感器比摄像头便宜，而且不用处理隐私问题。", { size: 14, fillWidth: true });

  const op2 = F(ct, "观点卡2", { layout: "VERTICAL", w: "fill", gap: 8, pad: 14, fill: CARD, radius: 20, shadow: true });
  const op2R = F(op2, "元信息行", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER" });
  const op2L = F(op2R, "左组", { layout: "HORIZONTAL", gap: 8, counter: "CENTER" });
  avatar(op2L, "我", AV_ORANGE, 26);
  T(op2L, "时间", "8 分钟前", { size: 11, color: FAINT });
  pill(op2R, "现场已回应", GREEN_BG, GREEN_TX);
  T(op2, "观点内容", "投放口的高度要照顾小学生，别按成年人身高设计。", { size: 14, fillWidth: true });

  // 底部麦克风悬浮钮
  const micWrap = F(s1, "麦克风区", { layout: "VERTICAL", w: 390, primary: "CENTER", counter: "CENTER", gap: 6, abs: true, x: 0, y: 844 - 108 });
  micWrap.resize(390, 108);
  const mic = F(micWrap, "麦克风按钮", { layout: "HORIZONTAL", w: 68, h: 68, primary: "CENTER", counter: "CENTER", gradient: "brand", radius: 34, shadow: true });
  const micIcon = figma.createNodeFromSvg(MIC_SVG); micIcon.name = "麦克风图标";
  mic.appendChild(micIcon);
  T(micWrap, "提示", "点击开麦发言", { size: 11, color: FAINT });

  // 遮罩 + 底部弹层
  const scrim = F(s1, "遮罩", { w: 390, h: 844, fillA: ["#101216", 0.44], abs: true, x: 0, y: 0 });
  const sheet = F(s1, "候选确认弹层", { layout: "VERTICAL", w: 390, gap: 14, padX: 20, padY: 12, fill: CARD, topRadius: 28, abs: true, x: 0, y: 844 - 330 });
  sheet.resize(390, 330);
  const handle = F(sheet, "拖拽柄", { w: 40, h: 4, fill: "#E5E7EB", radius: 2 });
  handle.layoutAlign = "CENTER";
  const shT = F(sheet, "标题行", { layout: "HORIZONTAL", w: "fill", gap: 8, counter: "CENTER" });
  pill(shT, "AI 候选", "#FFE9E3", BRAND_D, true);
  T(shT, "标题", "你的观点可能还没被现场听到", { size: 16, style: "Bold" });
  const quote = F(sheet, "原话卡", { layout: "VERTICAL", w: "fill", gap: 4, pad: 12, fill: BG, radius: 14 });
  T(quote, "原话", "「满溢检测的话，用重量传感器比摄像头便宜很多，而且不用处理隐私问题。」", { size: 13, color: "#3F454B", fillWidth: true });
  T(quote, "元信息", "你说的 · 2 分钟前", { size: 11, color: FAINT });
  const btns = F(sheet, "按钮行", { layout: "HORIZONTAL", w: "fill", gap: 12 });
  const b1 = F(btns, "请机器人提醒", { layout: "HORIZONTAL", h: 50, primary: "CENTER", counter: "CENTER", gradient: "brand", radius: 14, shadow: true });
  b1.layoutGrow = 1;
  T(b1, "label", "请机器人提醒", { size: 15, style: "Bold", color: "#FFFFFF" });
  const b2 = F(btns, "不必提醒", { layout: "HORIZONTAL", h: 50, primary: "CENTER", counter: "CENTER", fill: "#F3F4F6", radius: 14 });
  b2.layoutGrow = 1;
  T(b2, "label", "不必提醒", { size: 15, style: "Medium", color: INK });
  T(sheet, "说明", "机器人会在现场停顿时转述你的原话 · 剩余 98 秒", { size: 11, color: FAINT, fillWidth: true, align: "CENTER" });

  // ================= 屏 2 · 观点地图 =================
  const s2 = F(figma.currentPage, "屏2 会后-观点地图", { layout: "VERTICAL", w: 390, h: 844, fill: BG, radius: 40, clip: true, x: 490, y: 0 });

  const sb2 = F(s2, "状态栏", { layout: "HORIZONTAL", w: "fill", h: 54, primary: "SPACE_BETWEEN", counter: "CENTER", padX: 20, padY: 8 });
  T(sb2, "时间", "9:41", { size: 15, style: "Bold" });
  T(sb2, "网络", "5G", { size: 12, style: "Medium" });

  const hd = F(s2, "页头", { layout: "VERTICAL", w: "fill", gap: 4, padX: 20, padY: 4 });
  T(hd, "标题", "观点地图", { size: 26, style: "Bold" });
  T(hd, "信息", "回收箱方案评审 · 今天 15:00 · 3 人参会", { size: 12, color: GRAY });

  const stats = F(s2, "统计条", { layout: "HORIZONTAL", w: "fill", gap: 10, padX: 20, padY: 10 });
  function stat(num, label, bg, fg) {
    const st = F(stats, "统计·" + label, { layout: "VERTICAL", gap: 2, pad: 14, fill: CARD, radius: 16, shadow: true });
    st.layoutGrow = 1;
    T(st, "数字", num, { size: 22, style: "Bold", color: fg });
    T(st, "标签", label, { size: 11, color: GRAY });
  }
  stat("3", "个观点", CARD, INK);
  stat("1", "已回应", CARD, GREEN_TX);
  stat("2", "待核对", CARD, ORANGE_TX);

  const list = F(s2, "观点列表", { layout: "VERTICAL", w: "fill", h: "fill", gap: 14, padX: 20, padY: 6 });

  function opinionCard(cfg) {
    const c = F(list, "观点卡·" + cfg.who, { layout: "VERTICAL", w: "fill", gap: 10, pad: 16, fill: CARD, radius: 20, shadow: true });
    const r1 = F(c, "头部行", { layout: "HORIZONTAL", w: "fill", primary: "SPACE_BETWEEN", counter: "CENTER" });
    const who = F(r1, "身份组", { layout: "HORIZONTAL", gap: 10, counter: "CENTER" });
    avatar(who, cfg.av, cfg.avColor, 32);
    const whoTx = F(who, "名字组", { layout: "VERTICAL", gap: 1 });
    T(whoTx, "名字", cfg.who, { size: 13, style: "Bold" });
    T(whoTx, "时间", cfg.time, { size: 11, color: FAINT });
    pill(r1, cfg.tag, cfg.tagBg, cfg.tagFg);
    T(c, "观点", cfg.text, { size: 15, style: "Medium", fillWidth: true });
    if (cfg.reply) {
      const rb = F(c, "回应块", { layout: "VERTICAL", w: "fill", gap: 4, pad: 12, fill: GREEN_SOFT, radius: 14 });
      T(rb, "标签", "现场回应", { size: 11, style: "Bold", color: GREEN_TX });
      T(rb, "内容", cfg.reply, { size: 12, color: "#3F454B", fillWidth: true });
    }
    T(c, "查看原话", cfg.link, { size: 12, style: "Medium", color: BRAND });
  }

  opinionCard({
    who: "丙 · 线上", av: "丙", avColor: AV_ORANGE, time: "2 分钟处",
    tag: "已回应 · 现场确认", tagBg: GREEN_BG, tagFg: GREEN_TX,
    text: "满溢检测用重量传感器比摄像头便宜，而且不用处理隐私问题。",
    reply: "甲：重量传感器确实比摄像头便宜一半都不止；乙：不用担心拍到人，就这么定。",
    link: "查看原话 ›"
  });
  opinionCard({
    who: "甲、乙 · 现场", av: "甲", avColor: AV_INDIGO, time: "5 分钟处",
    tag: "待核对 · 讨论中", tagBg: ORANGE_BG, tagFg: ORANGE_TX,
    text: "箱体用折叠结构，运输方便——但结构强度和模具成本存疑。",
    link: "查看原话 ›"
  });
  opinionCard({
    who: "乙 · 现场", av: "乙", avColor: AV_CYAN, time: "6 分钟处",
    tag: "待核对", tagBg: ORANGE_BG, tagFg: ORANGE_TX,
    text: "折叠箱体的连接件可以用卡扣，拆装方便。",
    link: "查看原话 ›"
  });

  const ft = F(s2, "底部操作", { layout: "VERTICAL", w: "fill", pad: 20 });
  const exp = F(ft, "导出按钮", { layout: "HORIZONTAL", w: "fill", h: 52, primary: "CENTER", counter: "CENTER", fill: INK, radius: 16, shadow: true });
  T(exp, "label", "导出会议记录", { size: 15, style: "Bold", color: "#FFFFFF" });

  figma.currentPage.selection = [s1, s2];
  figma.viewport.scrollAndZoomIntoView([s1, s2]);
  figma.closePlugin("EffMeet2 高保真原型已生成");
}

main().catch(async err => {
  try {
    await figma.loadFontAsync({ family: FONT, style: "Regular" });
    const t = figma.createText();
    t.fontName = { family: FONT, style: "Regular" };
    t.characters = "PLUGIN ERROR: " + err.message + "\n\n" + (err.stack || "");
    t.fontSize = 14;
    t.fills = [{ type: "SOLID", color: { r: 0.9, g: 0.1, b: 0.1 } }];
    figma.currentPage.appendChild(t);
    t.x = 0; t.y = -260;
    figma.viewport.scrollAndZoomIntoView([t]);
  } catch (e2) {}
  figma.closePlugin("生成失败：" + err.message);
});
